        send_intent_at REAL,
        completed_at REAL,
        http_status_code INTEGER,
        request_id TEXT,
        receipt_sha256 TEXT,
        failure_category TEXT,
        provider_error_code TEXT,
        late_receipt_sha256 TEXT,
        UNIQUE (work_item_id,ordinal)
    );
