":1,\"type\":\"string\"},\"maxItems\":8,\"type\":\"array\"}},\"required\":[\"question_id\",\"response_kind\",\"status\",\"score\",\"summary\",\"information_as_of\",\"period_start\",\"period_end\",\"basis\",\"trend\",\"confidence\",\"metrics\",\"items\",\"evidence\",\"counterevidence\",\"watch_triggers\",\"missing_fields\",\"coverage\"],\"type\":\"object\"}\n数值指标尽量使用以下固定ID/单位/定义；没有数据则metrics=[]。其他指标只用custom.*，不可自动数值比较：{\"bank.cet1_ratio\":{\"definition\":\"核心一级资本/风险加权资产，注明当地监管口径\",\"unit\":\"percent\"},\"business.employees\":{\"definition\":\"人员数量，注明期末/平均及员工/外包范围\",\"unit\":\"count\"},\"business.segment_revenue\":{\"definition\":\"指定业务分部收入，说明对外与内部抵销\",\"unit\":\"currency\"},\"financial.capex\":{\"definition\":\"资本支出，区分维护与增长\",\"unit\":\"currency\"},\"financial.cash_runway\":{\"definition\":\"可用资金相对可核实消耗的期限，注明假设\",\"unit\":\"months\"},\"financial.diluted_eps\":{\"definition\":\"归属普通股的摊薄每股收益\",\"unit\":\"currency_per_share\"},\"financial.fcf\":{\"definition\":\"经营现金流减必要资本投入，列维护/增长/租赁口径\",\"unit\":\"currency\"},\"financial.net_debt\":{\"definition\":\"有息债务减可用现金，不套客户存款\",\"unit\":\"currency\"},\"financial.net_margin\":{\"definition\":\"净利润/营业收入，说明归属口径\",\"unit\":\"percent\"},\"financial.operating_margin\":{\"definition\":\"营业利润/营业收入，说明调整项目\",\"unit\":\"percent\"},\"financial.revenue\":{\"definition\":\"对外营业收入，须注明总额/净额和合并范围\",\"unit\":\"currency\"},\"financial.roe\":{\"definition\":\"归属普通股净利润/平均普通股权益，说明负/近零权益\",\"unit\":\"percent\"},\"financial.roic\":{\"definition\":\"税后经营利润/平均投入资本，说明商誉和资本调整\",\"unit\":\"percent\"},\"insurance.combined_ratio\":{\"definition\":\"赔付与费用占已赚保费比例，财险适用\",\"unit\":\"percent\"},\"operating.capacity_utilization\":{\"definition\":\"实际产出/可用产能，同口径产品与期间\",\"unit\":\"percent\"},\"operating.inventory_days\":{\"definition\":\"平均库存/匹配期间销货成本折算天数\",\"unit\":\"days\"},\"operating.net_revenue_retention\":{\"definition\":\"同一客户批次期末收入/期初收入，说明扩张/流失范围\",\"unit\":\"percent\"},\"operating.occupancy\":{\"definition\":\"已出租面积或可用单元占比，注明分母\",\"unit\":\"percent\"},\"ope