5378509996f6614472a691cfb5fba","module_release_id":"modrel_fc5de4a3dcce55866c8a2a83d82cdaa8caf8a3c59b6406d3a0ea75e7c9e01e74","question_definition_sha256":"a27556dbb12c4bd848cd5cd55c77e083e4c866c6b16e2f55a6a7d8247bc9967c","question_id":"IQS_09","question_semantic_sha256":"b83b4b57ae29c9e7d45107a69cdfe90f3c8b8258e7ecd293584085f2c45bd305","question_version":"1.0.0","run_id":"RUN_E2E","scan_id":"SCAN_E2E","schema_version":"1.1.0","scope":"entity","security_id":null,"segment_id":null,"task_mode":"primary","template_version":"3.2.0"},"subject_binding":{"identity_revision":1,"protocol":"stockqa.subject_context/1.0.0","question_contract":{"anchors":{"1":"核心个人流失即可破坏经营且没有接班能力","10":"人才与流程已形成可复制组织能力，关键人员更替有成功记录","5":"岗位基本齐备，但关键能力仍依赖少数人"},"comparison_role":"core","construct_id":"IQS_09","definition_sha256":"a27556dbb12c4bd848cd5cd55c77e083e4c866c6b16e2f55a6a7d8247bc9967c","dimension":"execution","evidence":["核心岗位梯队","人员流失","接班","制度化研发和销售","授权记录"],"id":"IQS_09","metric_contract":{"aggregation_role":"quality_core","critical_risk":false,"dimension":"quality","evidence_demands":{"counter_evidence_required":true,"require_durability_conditions":false,"require_net_economic_effect":false},"primary_metric_ref":"score.iqs_09","question_id":"IQS_09","replacement_for":null},"metric_id":"score.iqs_09","module_id":"common","priority":1,"prompt":"[IQS_09] 对象与口径={\"company\": \"Synthetic E2E issuer\", \"ticker\": \"ACME\", \"exchange\": \"XNAS\", \"as_of\": \"2026-10-10\", \"industry_modules\": [], \"cycle_position\": \"unknown\", \"recovery_review\": false, \"recovery_rationale\": \"\", \"entity_id\": \"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001\", \"security_id\": \"SEC_2c3b5e4f-0000-4b2c-9d3e-000000000001\"}\n组织能力是否足以延续，而不过度依赖少数关键个人？\n证据关注：核心岗位梯队；人员流失；接班；制度化研发和销售；授权记录\n评分锚点：1分=核心个人流失即可破坏经营且没有接班能力；5分=岗位基本齐备，但关键能力仍依赖少数人；10分=人才与流程已形成可复制组织能力，关键人员更替有成功记录。\n口径：分数衡量经济能力，不是行业内百分位；同业须同商业模式/阶段/期间/会计边界。；分别记录当前表现、已验证正常化能力、尚未兑现假设；亏损或低谷不自动否定壁垒，也不消除资金风险。；1/5/10锚点间给整数；8分需可核验多期或可比证据，高置信度不是高分；未知留空而非5。；评分与趋势分开：成熟稳固可高分，增长快但损毁价值仍低分。；分类待核实：只判断已确认的实体和问题，不套用未经证实的公司类型、行业或生命周期。\n\n实际联网搜索，仅用截止日前可得来源。不要下载公司文档。只输出符合下列schema的JSON；不使用score/description外层兼容包装。response_kind=score。事实不评分且score=null；未披露用insufficient_evidence，不等同不存在。已知部分可以answered+coverage.partial，并列缺项；关系和数值逐条绑定evidence_ids。canonical_entity_id/taxonomy_id只有已知主档映射才填，否则null，不自行创造。时间和模型由执行器另附，不在答案中自报执行回执。metrics使用明确单位、币种、期间和current/normalized/stress/forward口径；禁止混用。\n{\"$id\":\"urn:iqs:answer-content:1\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"properties\":{\"basis\":{\"enum\":[\"current\",\"trailing\",\"normalized\",\"stress\",\"forward\",\"not_applicable\"]},\"confidence\":{\"enum\":[\"high\",\"medium\",\"low\"]},\"counterevidence\":{\"maxLength\":600,\"minLength\":1,\"type\":\"string\"},\"coverage\":{\"additionalProperties\":false,\"properties\":{\"reason\":{\"maxLength\":350,\"minLength\":1,\"type\":\"string\"},\"status\":{\"enum\":[\"partial\",\"complete_for_scope\",\"unknown\",\"not_applicable\"]}},\"required\":[\"status\",\"reason\"],\"type\":\"object\"},\"evidence\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"claim\":{\"maxLength\":400,\"minLength\":1,\"type\":\"string\"},\"id\":{\"maxLength\":60,\"minLength\":1,\"type\":\"string\"},\"published_at\":{\"anyOf\":[{\"format\":\"date\",\"type\":\"string\"},{\"type\":\"null\"}]},\"title\":{\"maxLength\":200,\"minLength\":1,\"type\":\"string\"},\"url\":{\"format\":\"uri\",\"maxLength\":1800,\"pattern\":\"^https?://\",\"type\":\"string\"}},\"required\":[\"id\",\"title\",\"url\",\"published_at\",\"claim\"],\"type\":\"object\"},\"maxItems\":20,\"type\":\"array\"},\"information_as_of\":{\"anyOf\":[{\"format\":\"date\",\"type\":\"string\"},{\"type\":\"null\"}]},\"items\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"aliases\":{\"items\":{\"maxLength\":100,\"minLength\":1,\"type\":\"string\"},\"maxItems\":8,\"type\":\"array\"},\"canonical_entity_id\":{\"anyOf\":[{\"maxLength\":120,\"minLength\":1,