es":[],"stage":"unclassified","subtype":null},"comparison_group_id":null,"construct_id":"IQS_13","cycle_sensitive":false,"entity_id":"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001","evidence_review_status":"unreviewed","field_id":"score.iqs_13","information_cutoff":"2026-10-10","inputset_id":"INPUT_SYNTHETIC","method_id":"module-locked-v1/core-constructs-v1/6fc872b1165fef41/d854a94e7ab16ff6","module_package_id":"pkg_b5a41d8c9f89adba8d57cce1792b1cac8db5378509996f6614472a691cfb5fba","module_release_id":"modrel_fc5de4a3dcce55866c8a2a83d82cdaa8caf8a3c59b6406d3a0ea75e7c9e01e74","question_definition_sha256":"5734a8370a3c0f13bd51b8e6cbd6f115992007b378f47736f0991ec295047c88","question_id":"IQS_13","question_semantic_sha256":"d854a94e7ab16ff60c7025b188537664a6ac3c675cb814ef1c1bd873f9fec273","question_version":"1.0.0","run_id":"RUN_E2E","scan_id":"SCAN_E2E","schema_version":"1.1.0","scope":"entity","security_id":null,"segment_id":null,"task_mode":"primary","template_version":"3.2.0"},"subject_binding":{"identity_revision":1,"protocol":"stockqa.subject_context/1.0.0","question_contract":{"anchors":{"1":"存在重大侵占、利益输送或权利缺陷且未解决","10":"长期交易与治理记录证明普通股东能公平分享经济利益","5":"基本权益受保护，但制衡或交易公平性仍有疑问"},"comparison_role":"core","construct_id":"IQS_13","critical":true,"definition_sha256":"5734a8370a3c0f13bd51b8e6cbd6f115992007b378f47736f0991ec295047c88","dimension":"governance","evidence":["关联交易","资金占用","控制权与现金权","资产转移","少数股东保护"],"id":"IQS_13","metric_contract":{"aggregation_role":"quality_core","critical_risk":true,"dimension":"quality","evidence_demands":{"counter_evidence_required":true,"require_durability_conditions":false,"require_net_economic_effect":false},"primary_metric_ref":"score.iqs_13","question_id":"IQS_13","replacement_for":null},"metric_id":"score.iqs_13","module_id":"common","priority":1,"prompt":"[IQS_13] 对象与口径={\"company\": \"Synthetic E2E issuer\", \"ticker\": \"ACME\", \"exchange\": \"XNAS\", \"as_of\": \"2026-10-10\", \"industry_modules\": [], \"cycle_position\": \"unknown\", \"recovery_review\": false, \"recovery_rationale\": \"\", \"entity_id\": \"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001\", \"security_id\": \"SEC_2c3b5e4f-0000-4b2c-9d3e-000000000001\"}\n管理层和控制人是否有公平对待普通股东的实际记录？\n证据关注：关联交易；资金占用；控制权与现金权；资产转移；少数股东保护\n评分锚点：1分=存在重大侵占、利益输送或权利缺陷且未解决；5分=基本权益受保护，但制衡或交易公平性仍有疑问；10分=长期交易与治理记录证明普通股东能公平分享经济利益。\n口径：分数衡量经济能力，不是行业内百分位；同业须同商业模式/阶段/期间/会计边界。；分别记录当前表现、已验证正常化能力、尚未兑现假设；亏损或低谷不自动否定壁垒，也不消除资金风险。；1/5/10锚点间给整数；8分需可核验多期或可比证据，高置信度不是高分；未知留空而非5。；评分与趋势分开：成熟稳固可高分，增长快但损毁价值仍低分。；分类待核实：只判断已确认的实体和问题，不套用未经证实的公司类型、行业或生命周期。\n\n实际联网搜索，仅用截止日前可得来源。不要下载公司文档。只输出符合下列schema的JSON；不使用score/description外层兼容包装。response_kind=score。事实不评分且score=null；未披露用insufficient_evidence，不等同不存在。已知部分可以answered+coverage.partial，并列缺项；关系和数值逐条绑定evidence_ids。canonical_entity_id/taxonomy_id只有已知主档映射才填，否则null，不自行创造。时间和模型由执行器另附，不在答案中自报执行回执。metrics使用明确单位、币种、期间和current/normalized/stress/forward口径；禁止混用。\n{\"$id\":\"urn:iqs:answer-content:1\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"properties\":{\"basis\":{\"enum\":[\"current\",\"trailing\",\"normalized\",\"stress\",\"forward\",\"not_applicable\"]},\"confidence\":{\"enum\":[\"high\",\"medium\",\"low\"]},\"counterevidence\":{\"maxLength\":600,\"minLength\":1,\"type\":\"string\"},\"coverage\":{\"additionalProperties\":false,\"properties\":{\"reason\":{\"maxLength\":350,\"minLength\":1,\"type\":\"string\"},\"status\":{\"enum\":[\"partial\",\"complete_for_scope\",\"unknown\",\"not_applicable\"]}},\"required\":[\"status\",\"reason\"],\"type\":\"object\"},\"evidence\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"claim\":{\"maxLength\":400,\"minLength\":1,\"type\":\"string\"},\"id\":{\"maxLength\":60,\"minLength\":1,\"type\":\"string\"},\"published_at\":{\"anyOf\":[{\"format\":\"date\",\"type\":\"string\"},{\"type\":\"null\"}]},\"title\":{\"maxLength\":200,\"minLength\":1,\"type\":\"string\"},\"url\":{\"format\":\"uri\",\"maxLength\":1800,\"pattern\":\"^https?://\",\"type\":\"string\"}},\"requ