492d7307d07153411abfb","question":"失去关键客户、供应来源、产地或系统时，公司能否在可承受代价内恢复？","rubric_version":"1.0.0","scope":"entity","semantic_sha256":"f3968cf78ea10e8938c5a5d5180688b84fba3fabbf594a54a33c7fa563dc5ed4"},"subject_ref":{"analysis_subject_id":"ASJ_11111111-1111-4111-8111-111111111111","analysis_subject_revision":1,"entity_id":"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001","listing_id":null,"perimeter_sha256":"42b2c8411d22b2ac87cd0f3a5fef9fbc34f310103f28ef459c6d5c8752a17e15","primary_issuer_id":"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001","scope":"entity","scope_id":"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001","security_id":null,"segment_id":null}},"work_prompt_sha256":"4780dc931f56c4c16f6ebc126fc72dc8a152f68ad7c492d7307d07153411abfb"},"IQS_18":{"frozen_prompt_sha256":"65bd11dd3d60b396928628a1bbeff679811e828c881169ebc31abae34f39a612","metadata":{"cohort":{"company_type":"unclassified","industries":[],"stage":"unclassified","subtype":null},"comparison_group_id":null,"construct_id":"IQS_18","cycle_sensitive":false,"entity_id":"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001","evidence_review_status":"unreviewed","field_id":"score.iqs_18","information_cutoff":"2026-10-10","inputset_id":"INPUT_SYNTHETIC","method_id":"module-locked-v1/core-constructs-v1/6fc872b1165fef41/1cd584b6cf4a0b2e","module_package_id":"pkg_b5a41d8c9f89adba8d57cce1792b1cac8db5378509996f6614472a691cfb5fba","module_release_id":"modrel_fc5de4a3dcce55866c8a2a83d82cdaa8caf8a3c59b6406d3a0ea75e7c9e01e74","question_definition_sha256":"6f03dbaaf8f4dd9514fa043d7a9844f3f86c7ae904b0a6f2a8c28ef39985f271","question_id":"IQS_18","question_semantic_sha256":"1cd584b6cf4a0b2e54db71e930467c08cb2964778d84b4a192bcabf46266777a","question_version":"2.0.0","run_id":"RUN_E2E","scan_id":"SCAN_E2E","schema_version":"1.1.0","scope":"entity","security_id":null,"segment_id":null,"task_mode":"primary","template_version":"3.2.0"},"subject_binding":{"identity_revision":1,"protocol":"stockqa.subject_context/1.0.0","question_contract":{"anchors":{"1":"核心价值已面临重大不可逆损害，缺少可行防御","10":"主要失效路径的暴露有限或防御经验证，能在压力下保持核心价值","5":"风险可识别且有应对，但有效性与缓冲尚未充分验证"},"comparison_role":"core","construct_id":"IQS_18","definition_sha256":"6f03dbaaf8f4dd9514fa043d7a9844f3f86c7ae904b0a6f2a8c28ef39985f271","dimension":"resilience","evidence":["最重要的一至两项技术替代、渠道迁移、监管/环境约束或商业模式失效，不按热点词罗列","受影响的分部、客户场景及其当前利润/资产敞口","替代路径、可能速度、公司防御或转移能力及所需投入","能推翻结构性损害判断的反证和观察期限"],"id":"IQS_18","metric_contract":{"aggregation_role":"quality_core","critical_risk":false,"dimension":"quality","evidence_demands":{"counter_evidence_required":true,"require_durability_conditions":true,"require_net_economic_effect":false},"primary_metric_ref":"score.iqs_18","question_id":"IQS_18","replacement_for":null},"metric_id":"score.iqs_18","module_id":"common","priority":1,"prompt":"[IQS_18] 对象与口径={\"company\": \"Synthetic E2E issuer\", \"ticker\": \"ACME\", \"exchange\": \"XNAS\", \"as_of\": \"2026-10-10\", \"industry_modules\": [], \"cycle_position\": \"unknown\", \"recovery_review\": false, \"recovery_rationale\": \"\", \"entity_id\": \"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001\", \"security_id\": \"SEC_2c3b5e4f-0000-4b2c-9d3e-000000000001\"}\n最可能永久损害核心业务价值的一至两项实质变化，哪些会绕过现有优势，公司有哪些经验证的防御？\n证据关注：最重要的一至两项技术替代、渠道迁移、监管/环境约束或商业模式失效，不按热点词罗列；受影响的分部、客户场景及其当前利润/资产敞口；替代路径、可能速度、公司防御或转移能力及所需投入；能推翻结构性损害判断的反证和观察期限\n评分锚点：1分=核心价值已面临重大不可逆损害，缺少可行防御；5分=风险可识别且有应对，但有效性与缓冲尚未充分验证；10分=主要失效路径的暴露有限或防御经验证，能在压力下保持核心价值。\n口径：分数衡量经济能力，不是行业内百分位；同业须同商业模式/阶段/期间/会计边界。；分别记录当前表现、已验证正常化能力、尚未兑现假设；亏损或低谷不自动否定壁垒，也不消除资金风险。；1/5/10锚点间给整数；8分需可核验多期或可比证据，高置信度不是高分；未知留空而非5。；评分与趋势分开：成熟稳固可高分，增长快但损毁价值仍低分。；分类待核实：只判断已确认的实体和问题，不套用未经证实的公司类型、行业或生命周期。\n\n实际联网搜索，仅用截止日前可得来源。不要下载公司文档。只输出符合下列schema的JSON；不使用score/description外层兼容包装。response_kind=score。事实不评分且score=null；未披露用insufficient_evidence，不等同不存在。已知部分可以answered+coverage.partial，并列缺项；关系和数值逐条绑定evidence_ids。canonical_entity_id/taxonomy_id只有已知主档映射才填，否则null，不自行创造。时间和模型由执行器另附，不在答案中自报执行回执。metrics使用明确单位、币种、期间和current/normalized/stress/forward口径；禁止混用。\n{\"$id\":\"urn:iqs:answer-content:1\",\"$schema\":\"http