12629b195016f2acce88ae0a1b0d301021cd5d82"},"IQS_20":{"frozen_prompt_sha256":"722ec9576e268c9b975764089eba9e21fd24dab5e3a91761c617e0da43700db8","metadata":{"cohort":{"company_type":"unclassified","industries":[],"stage":"unclassified","subtype":null},"comparison_group_id":null,"construct_id":"IQS_20","cycle_sensitive":false,"entity_id":"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001","evidence_review_status":"unreviewed","field_id":"score.iqs_20","information_cutoff":"2026-10-10","inputset_id":"INPUT_SYNTHETIC","method_id":"module-locked-v1/core-constructs-v1/6fc872b1165fef41/36c87f138bc0f891","module_package_id":"pkg_b5a41d8c9f89adba8d57cce1792b1cac8db5378509996f6614472a691cfb5fba","module_release_id":"modrel_fc5de4a3dcce55866c8a2a83d82cdaa8caf8a3c59b6406d3a0ea75e7c9e01e74","question_definition_sha256":"f0b94ca96c7e82be38547bc0306752c630360ebdb9c5fdf4a35fda5c5831e860","question_id":"IQS_20","question_semantic_sha256":"36c87f138bc0f89163f3b1a133af90cad0d70a9186e3a9b6d62fdebac1cd96c3","question_version":"2.0.0","run_id":"RUN_E2E","scan_id":"SCAN_E2E","schema_version":"1.1.0","scope":"entity","security_id":null,"segment_id":null,"task_mode":"primary","template_version":"3.2.0"},"subject_binding":{"identity_revision":1,"protocol":"stockqa.subject_context/1.0.0","question_contract":{"anchors":{"1":"增长主要依赖叙事、并表或远期假设；或可见的新业务收益不足以弥补存量利润损失与必要投入","10":"主要驱动有连续可核实的付费、收入和利润转化；考虑存量业务变化、必要投入与摊薄后仍能持续增厚股东经济利益","5":"客户需求和转化路径有部分验证，但新旧业务合并后的利润与每股净效果仍不确定"},"comparison_role":"core","construct_id":"IQS_20","definition_sha256":"f0b94ca96c7e82be38547bc0306752c630360ebdb9c5fdf4a35fda5c5831e860","dimension":"growth","evidence":["自然量价与并购汇率拆分","从产品/试点、付费采用、重复购买到收入和利润的实际阶段与证据","新增业务的利润池归属、客户议价及可持续单位经济","对存量业务的替代/蚕食和损失的利润贡献","必要转型投入、融资需求及摊薄后的净股东经济效果"],"id":"IQS_20","metric_contract":{"aggregation_role":"growth_core","critical_risk":false,"dimension":"growth","evidence_demands":{"counter_evidence_required":true,"require_durability_conditions":false,"require_net_economic_effect":true},"primary_metric_ref":"score.iqs_20","question_id":"IQS_20","replacement_for":null},"metric_id":"score.iqs_20","module_id":"common","priority":1,"prompt":"[IQS_20] 对象与口径={\"company\": \"Synthetic E2E issuer\", \"ticker\": \"ACME\", \"exchange\": \"XNAS\", \"as_of\": \"2026-10-10\", \"industry_modules\": [], \"cycle_position\": \"unknown\", \"recovery_review\": false, \"recovery_rationale\": \"\", \"entity_id\": \"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001\", \"security_id\": \"SEC_2c3b5e4f-0000-4b2c-9d3e-000000000001\"}\n未来增长的主要驱动是否已被验证能从客户需求转为可持续利润，并扣除对存量业务、必要投入与股权融资的影响？\n证据关注：自然量价与并购汇率拆分；从产品/试点、付费采用、重复购买到收入和利润的实际阶段与证据；新增业务的利润池归属、客户议价及可持续单位经济；对存量业务的替代/蚕食和损失的利润贡献；必要转型投入、融资需求及摊薄后的净股东经济效果\n评分锚点：1分=增长主要依赖叙事、并表或远期假设；或可见的新业务收益不足以弥补存量利润损失与必要投入；5分=客户需求和转化路径有部分验证，但新旧业务合并后的利润与每股净效果仍不确定；10分=主要驱动有连续可核实的付费、收入和利润转化；考虑存量业务变化、必要投入与摊薄后仍能持续增厚股东经济利益。\n口径：分数衡量经济能力，不是行业内百分位；同业须同商业模式/阶段/期间/会计边界。；分别记录当前表现、已验证正常化能力、尚未兑现假设；亏损或低谷不自动否定壁垒，也不消除资金风险。；1/5/10锚点间给整数；8分需可核验多期或可比证据，高置信度不是高分；未知留空而非5。；评分与趋势分开：成熟稳固可高分，增长快但损毁价值仍低分。；分类待核实：只判断已确认的实体和问题，不套用未经证实的公司类型、行业或生命周期。\n\n实际联网搜索，仅用截止日前可得来源。不要下载公司文档。只输出符合下列schema的JSON；不使用score/description外层兼容包装。response_kind=score。事实不评分且score=null；未披露用insufficient_evidence，不等同不存在。已知部分可以answered+coverage.partial，并列缺项；关系和数值逐条绑定evidence_ids。canonical_entity_id/taxonomy_id只有已知主档映射才填，否则null，不自行创造。时间和模型由执行器另附，不在答案中自报执行回执。metrics使用明确单位、币种、期间和current/normalized/stress/forward口径；禁止混用。\n{\"$id\":\"urn:iqs:answer-content:1\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"properties\":{\"basis\":{\"enum\":[\"current\",\"trailing\",\"normalized\",\"stress\",\"forward\",\"not_applicable\"]},\"confidence\":{\"enum\":[\"high\",\"medium\",\"low\"]},\"counterevidence\":{\"maxLength\":600,\"minLength\":1,\"type\":\"string\"},\"coverage\":{\"additionalProperties\":false,\"properties\":{\"reason\":{\"maxLength\":350,\"minLength\":1,\"type\":\"string\"},\"status\":{\"enum\":[\"partial\",\"complete_for_scope\",\"unknown\",\"not_applicable\"]}},\"required\":[\"stat