INSERT INTO "quick_scan_subject_send_receipt" VALUES('ATTEMPT_bd7f27db46894095b4dc95b474bd70ab','WORK_fdf3d1827ec24c34822117c0331b5fd6','sdr_8c6f8c34469a967188425b3bc3fad591525f95cf95a4780fff62b56655950c08','32714e22b0d94b2dff1464398cde65eb66979fd48fd2c6f4a867ec05b7d1374a','{"dispatch_request":{"dispatch_identity_snapshot_sha256":"1d1fdd5b6f86e5ebd3520b84cf51ebf8fbefef8a5365de64d7aa3b4ed0c4b289","dispatch_manifest_sha256":"68b9aea21566e273e46008b9306016fc1e5f22a862cefa1cff92270317f75f02","dispatch_prompt_sha256":"0c5e2b1a1f3d790a522860aad25f780a8e768176ed7723b0fcc4804f5095c299","dispatch_work_prompt_sha256":"f5049cc584e0da5dae91d0e44a1396c5b4bfb0f3ef900d050ffe45c9920bb142","execution_attempt_id":"a8fc4f76-8103-4d5f-87ab-0d4cea38f12d","field_id":"score.iqs_01","identity_revision":1,"information_cutoff":"2026-10-10","method_id":"module-locked-v1/core-constructs-v1/6fc872b1165fef41/069a97a668580620","model_requested":"fixture-model","module_package_id":"pkg_b5a41d8c9f89adba8d57cce1792b1cac8db5378509996f6614472a691cfb5fba","module_release_id":"modrel_fc5de4a3dcce55866c8a2a83d82cdaa8caf8a3c59b6406d3a0ea75e7c9e01e74","protocol":"stockwiki.subject_dispatch_request/1.1.0","provider":"openai","question_contract":{"anchors":{"1":"产品价值不足，主要靠补贴或推销维持需求","10":"客户价值清楚且有行为证据，付费与复购可持续","5":"客户价值成立但可轻易替换、支付意愿一般"},"comparison_role":"core","construct_id":"IQS_01","definition_sha256":"e49b91646870da125d3e4a03e7cadd2ffb93e24638e7c0cb801dfb5909e3bebc","dimension":"business","evidence":["客户实际解决的问题","总使用成本","独立客户复购与付费","停止使用的后果"],"id":"IQS_01","metric_contract":{"aggregation_role":"quality_core","critical_risk":false,"dimension":"quality","evidence_demands":{"counter_evidence_required":true,"require_durability_conditions":false,"require_net_economic_effect":false},"primary_metric_ref":"score.iqs_01","question_id":"IQS_01","replacement_for":null},"metric_id":"score.iqs_01","module_id":"common","priority":1,"prompt":"[IQS_01] 对象与口径={\"company\": \"Synthetic E2E issuer\", \"ticker\": \"ACME\", \"exchange\": \"XNAS\", \"as_of\": \"2026-10-10\", \"industry_modules\": [], \"cycle_position\": \"unknown\", \"recovery_review\": false, \"recovery_rationale\": \"\", \"entity_id\": \"ENT_1b2a4d3e-0000-4a1b-8c2d-000000000001\", \"security_id\": \"SEC_2c3b5e4f-0000-4b2c-9d3e-000000000001\"}\n客户购买公司的产品或服务，是否获得足以支持持续付费的真实价值？\n证据关注：客户实际解决的问题；总使用成本；独立客户复购与付费；停止使用的后果\n评分锚点：1分=产品价值不足，主要靠补贴或推销维持需求；5分=客户价值成立但可轻易替换、支付意愿一般；10分=客户价值清楚且有行为证据，付费与复购可持续。\n口径：分数衡量经济能力，不是行业内百分位；同业须同商业模式/阶段/期间/会计边界。；分别记录当前表现、已验证正常化能力、尚未兑现假设；亏损或低谷不自动否定壁垒，也不消除资金风险。；1/5/10锚点间给整数；8分需可核验多期或可比证据，高置信度不是高分；未知留空而非5。；评分与趋势分开：成熟稳固可高分，增长快但损毁价值仍低分。；分类待核实：只判断已确认的实体和问题，不套用未经证实的公司类型、行业或生命周期。\n\n实际联网搜索，仅用截止日前可得来源。不要下载公司文档。只输出符合下列schema的JSON；不使用score/description外层兼容包装。response_kind=score。事实不评分且score=null；未披露用insufficient_evidence，不等同不存在。已知部分可以answered+coverage.partial，并列缺项；关系和数值逐条绑定evidence_ids。canonical_entity_id/taxonomy_id只有已知主档映射才填，否则null，不自行创造。时间和模型由执行器另附，不在答案中自报执行回执。metrics使用明确单位、币种、期间和current/normalized/stress/forward口径；禁止混用。\n{\"$id\":\"urn:iqs:answer-content:1\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"properties\":{\"basis\":{\"enum\":[\"current\",\"trailing\",\"normalized\",\"stress\",\"forward\",\"not_applicable\"]},\"confidence\":{\"enum\":[\"high\",\"medium\",\"low\"]},\"counterevidence\":{\"maxLength\":600,\"minLength\":1,\"type\":\"string\"},\"coverage\":{\"additionalProperties\":false,\"properties\":{\"reason\":{\"maxLength\":350,\"minLength\":1,\"type\":\"string\"},\"status\":{\"enum\":[\"partial\",\"complete_for_scope\",\"unknown\",\"not_applicable\"]}},\"required\":[\"status\",\"reason\"],\"type\":\"object\"},\"evidence\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"claim\":{\"maxLength\":400,\"minLength\":1,\"type\":\"string\"},\"id\":{\"maxLength\":60,\"minLength\":1,\"type\":\"string\"},\"published_at\":{\"anyOf\":[{\"format\":\"date\",\"type\":\"string\"},{\"type\":\"null\"}]},\"title\":{\"maxLength\":200,\"minLength\":1,\"type\":\"string\"},\"url\":{\"format\":\"uri\",\"maxLength\":1800,\"pattern\":\"^https?://\",\"type\":\"string\"}},\"required\":[\"id\",\"title\",\"url\",\"published_at\",\"claim\"],\"type\":\"object\"},\"maxItems\":20,\"type\":\"array\"},\"information_as_of\":{\"anyOf\":[{\"format\":\"date\",\"type\":\"string\"},{\"type\":\"null\"}]},\"items\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"aliases\":{\"items\":{\"maxLength\":100,\"minLength\":1,\"type\":\"string\"},\"maxItems\":8,\"type\":\"array\"},\"canonical_entity_id\":{\"anyOf\":[{\"maxLength\":120,\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}]},\"commercial_stage\":{\"enum\":[\"research\",\"pilot\",\"qualified\",\"commercial\",\"discontinued\",\"unknown\",\"not_applicable\"]},\"confidence\":{\"enum\":[\"high\",\"medium\",\"low\"]},\"description\":{\"maxLength\":500,\"minLength\":1,\"type\":\"string\"},\"evidence_ids\":{\"items\":{\"maxLength\":60,\"minLength\":1,\"type\":\"string\"},\"maxItems\":10,\"type\":\"array\"},\"metrics\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"basis\":{\"enum\":[\"current\",\"trailing\",\"normalized\",\"stress\",\"forward\",\"not_applicable\"]},\"currency\":{\"anyOf\":[{\"pattern\":\"^[A-Z]{3}$\",\"type\":\"string\"},{\"type\":\"null\"}]},\"definition\":{\"maxLength\":350,\"minLength\":1,\"type\":\"string\"},\"evidence_ids\":{\"items\":{\"maxLength\":60,\"minLength\":1,\"type\":\"string\"},\"maxItems\":10,\"type\":\"array\"},\"metric_id\":{\"maxLength\":120,\"minLength\":1,\"type\":\"string\"},\"period_end\":{\"anyOf\":[{\"format\":\"date\",\"type\":\"string\"},{\"type\":\"null\"}]},\"period_start\":{\"anyOf\":[{\"format\":\"date\",\"type\":\"string\"},{\"type\":\"null\"}]},\"unit\":{\"enum\":[\"percent\",\"ratio\",\"currency\",\"currency_per_share\",\"count\",\"days\",\"months\",\"years\",\"units\",\"other\"]},\"unit_detail\":{\"anyOf\":[{\"maxLength\":80,\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}]},\"value\":{\"anyOf\":[{\"t